void dei_ask_fiq_mode_leave(void)
{
    dei_ask_atomic_enter();
    {
        isr_set_vector (ISR_ID_EINT_1, 15 , ISR_TYPE_IRQ , dei_ask_handler_irq);
        
        fiq_unregister(dei_ask_handler_fiq);
        
        dei_ask_ext_init();
    }
    dei_ask_atomic_leave();               
}

